private void permute(int[] nums, int[] indices, int i, List<List<Integer>> permutations) {
    if (i == nums.length) {
        List<Integer> perm = new ArrayList<>();
        for (int j = 0; j < nums.length; j++) {
            perm.add(nums[indices[j]]);
        }
        permutations.add(perm);
    } else {
        for (int j = i; j < nums.length; j++) {
            swap(indices, i, j);
            permute(nums, indices, i + 1, permutations);
            swap(indices, i, j);
        }
    }
