public class OilDepositsCounter {
    public static int countOilDeposits(char[][] grid) {
        Set<Integer> deposits = new HashSet<>();
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '@') {
                    int currentDeposit = getDeposit(grid, i, j);
                    if (!deposits.contains(currentDeposit)) {
                        deposits.add(currentDeposit);
                    }
                }
            }
        }
        return deposits.size();
    }

    private static int getDeposit(char[][] grid, int x, int y) {
        int current = 0;
        for (int i = x - 1; i <= x + 1; i++) {
            for (int j = y - 1; j <= y + 1; j++) {
                if (i >= 0 && i < grid.length && j >= 0 && j < grid[i].length && grid[i][j] == '@') {
                    current++;
                }
            }
        }
        return current;
    }
}

