    // Add the starting n-tersection to the queue
    queue.add(arrayToString(start));

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        String current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (arrayEquals(stringToArray(current), end)) {
            return "can be travelled";
        }

        // Get the possible next n-tersections from the current n-tersection
        int nextX = current.charAt(0) + 1;
        int nextY = current.charAt(1) + 1;

        // If the possible next n-tersections are not out of bounds and are not blocked by a wall, add them to the queue
        if (nextX < n && nextY < n && paths[nextX][nextY] != 1) {
            queue.add(arrayToString(new int[] {nextX, nextY}));
        }

        // If the current n-tersection is not a wall, add its possible next n-tersections to the queue
        if (paths[current.charAt(0)][current.charAt(1)] != 1) {
            for (int[] direction : DIRECTIONS) {
                int nextX = current.charAt(0) + direction[0];
                int nextY = current.charAt(1) + direction[1];
                if (nextX >= 0 && nextX < n && nextY >= 0 && nextY < n && paths[nextX][nextY] != 1) {
                    queue.add(arrayToString(new int[] {nextX, nextY}));
                }
            }
        }
    }

    // If the queue is empty and the ending n-tersection was not reached, return "cannot be travelled"
    return "cannot be travelled";
}

