    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n * n];

    // Initialize a queue to perform BFS
    Queue<Integer> queue = new LinkedList<>();

    // Mark the starting n-tersection as visited and enqueue it
    visited[start[0] * n + start[1]] = true;
    queue.offer(start[0] * n + start[1]);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Dequeue an n-tersection from the queue
        int current = queue.poll();

        // If the dequeued n-tersection is the ending n-tersection, return "can be travelled"
        if (current == end[0] * n + end[1]) {
            return "can be travelled";
        }

        // Loop through all possible paths from the dequeued n-tersection
        for (int i = 0; i < paths.length; i++) {
            // If the path is not blocked and the destination n-tersection is not visited, mark it as visited and enqueue it
            if (paths[current][i] != -1 && !visited[paths[current][i]]) {
                visited[paths[current][i]] = true;
                queue.offer(paths[current][i]);
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been reached, return "cannot be travelled"
    return "cannot be travelled";
}

