        if (paths[i] == null || paths[i].length < n) {
            return "cannot be travelled";
        }
        for (int j = 0; j < n; j++) {
            if (paths[i][j] == 1) {
                if (start[i] == -1 || end[j] == -1) {
                    continue;
                }
                if (start[i] == j) {
