    while (!queue.isEmpty()) {
        // Dequeue the next n-tersection
        int[] current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // Loop through all possible paths from the current n-tersection
        for (int[] path : paths) {
            // If the path is not valid, continue to the next path
            if (!isValidPath(current, path)) {
                continue;
            }

            // Calculate the coordinates of the n-tersection at the end of the path
            int[] next = getNextIntersection(current, path);

            // If the n-tersection has not been visited, mark it as visited and enqueue it
            if (!visited.contains(Arrays.toString(next))) {
                visited.add(Arrays.toString(next));
                queue.offer(next);
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
    return "cannot be travelled";
}

// Helper method to check if a path is valid
private static boolean isValidPath(int[] current, int[] path) {
    // Check if the path is within the bounds of the n-teresting space
    if (path[0] < 0 || path[0] >= n || path[1] < 0 || path[1] >= n) {
        return false;
    }

    // Check if the path is not a diagonal
    if (Math.abs(path[0] - current[0]) == Math.abs(path[1] - current[1])) {
        return false;
    }

    return true;
}

// Helper method to calculate the coordinates of the n-tersection at the end of a path
private static int[] getNextIntersection(int[] current, int[] path) {
    return new int[] { current[0] + path[0], current[1] + path[1] };
