private static String canTravelMazeHelper(int n, int[] start, int[] end, int[][] paths, int currentRow, int currentCol) {
    // If the current n-tersection is the ending n-tersection, return "can be travelled"
    if (currentRow == end[0] && currentCol == end[1]) {
        return "can be travelled";
    }

    // Check if the current n-tersection is valid and has not been visited before
    if (isValid(n, currentRow, currentCol) && !isVisited(paths, currentRow, currentCol)) {
        // Mark the current n-tersection as visited
        paths[currentRow][currentCol] = 1;

        // Recursively call the helper function for each valid adjacent n-tersection
        int[] adjacent = getAdjacent(n, currentRow, currentCol);
        for (int i = 0; i < adjacent.length; i++) {
            int row = adjacent[i][0];
            int col = adjacent[i][1];
            String result = canTravelMazeHelper(n, start, end, paths, row, col);
            if (result == "can be travelled") {
                return result;
            }
        }

        // If none of the adjacent n-tersections can be travelled to, return "cannot be travelled"
        return "cannot be travelled";
    } else {
        // If the current n-tersection is invalid or has been visited before, return "cannot be travelled"
        return "cannot be travelled";
    }
}

private static boolean isValid(int n, int row, int col) {
    return row >= 0 && row < n && col >= 0 && col < n;
}

private static boolean isVisited(int[][] paths, int row, int col) {
    return paths[row][col] == 1;
}

private static int[][] getAdjacent(int n, int row, int col) {
    int[][] adjacent = {{row - 1, col}, {row, col - 1}, {row, col + 1}, {row + 1, col}};
    return adjacent;
}

