public double trimMean(int[] arr) {
  int len = arr.length;
  int threshold = (int) Math.floor(len * 0.05);
  int l = threshold;
  int r = len - threshold - 1;
  double sum = 0.0;
  while (l <= r) {
    sum += arr[l] + arr[r];
    l++;
    r--;
  }
  double mean = sum / (len - threshold * 2);
  return Math.floor(mean * 100000) / 100000.0;
}

