public double trimMean(int[] arr) {
    // Calculate the size of the 5% trim
    int trimSize = (int) Math.round(arr.length * 0.05);

    // Sort the array to find the smallest and largest 5% of the elements
    Arrays.sort(arr);
    int[] trim = new int[trimSize];
    System.arraycopy(arr, 0, trim, 0, trimSize);

    // Calculate the mean of the remaining elements
    double sum = 0.0;
    for (int i = trimSize; i < arr.length - trimSize; i++) {
        sum += arr[i];
    }
    double mean = sum / (arr.length - 2 * trimSize);

    // Return the mean with an error within 10^-5
    return Math.round(mean * 1e5) / 1e5;
}
