public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with edges and hasApple values
    Graph graph = new Graph(edges);
    int minTime = 0;

    // Perform Dijkstra's algorithm on the graph starting from node 0
    PriorityQueue<Node> queue = new PriorityQueue<>(graph.getNodes().size(), new Comparator<Node>() {
        @Override
        public int compare(Node o1, Node o2) {
            return Long.compare(o1.getDist(), o2.getDist());
        }
    });
    queue.add(graph.getNodes().get(0));
    while (!queue.isEmpty()) {
        Node node = queue.poll();
        if (node.isVisited()) {
            continue;
        }
        node.setVisited(true);
        for (Edge edge : node.getEdges()) {
            Node neighbor = edge.getNeighbor(node);
            if (!neighbor.isVisited() && neighbor.getDist() > node.getDist() + edge.getCost()) {
                neighbor.setDist(node.getDist() + edge.getCost());
                queue.add(neighbor);
            }
        }
        minTime = Math.max(minTime, node.getDist());
    }

    // Return the minimum time required to collect all the apples and return to node 0
    return minTime;
}

class Graph {
    List<Node> nodes;
    List<Edge> edges;
    boolean[] hasApple;

    public Graph(int[][] edges, boolean[] hasApple) {
        this.nodes = new ArrayList<>();
        this.edges = new ArrayList<>();
        this.hasApple = hasApple;
        for (int i = 0; i < edges.length; i++) {
            Node node = new Node(i);
            nodes.add(node);
            for (int j = 0; j < edges[i].length; j++) {
                Node neighbor = nodes.get(edges[i][j]);
                Edge edge = new Edge(node, neighbor, 1);
                edges.add(edge);
                node.addEdge(edge);
            }
        }
    }

    public List<Node> getNodes() {
        return nodes;
    }

    public List<Edge> getEdges() {
        return edges;
    }
}

