    private boolean canSplit(int[] nums) {
        // Calculate the expression of the sum of the elements of the array
        int sum = 0;
        for (int num : nums) {
            sum += num;
        }
        int average = sum / nums.length;

        // Check if the average is an integer
        if (sum % nums.length != 0) {
            return false;
        }

        // Check each possible partition
        for (int i = 0; i < nums.length; i++) {
