                subSum += nums[j];
            }
            for (int j = 0; j < nums.length; j++) {
                subSum += nums[j];
            }

            if (subSum / (nums.length - i) == average) {
                return true;
            }
        }

        // If no partitions can split the array into two arrays with the same average, return false
        return false;
    }
