public class Solution {
    public boolean hasAllCodes(String s, int k) {
        // Initialize a set to store all unique binary strings of length k
        Set<String> set = new HashSet<>();

        // Loop through the string s and add each binary string of length k to the set
        for (int i = 0; i <= s.length() - k; i++) {
            String binaryString = s.substring(i, i + k);
            set.add(binaryString);
        }

        // Return true if the size of the set is 2^k, which means all possible binary strings of length k are contained in the set
        return set.size() == (int) Math.pow(2, k);
    }
