public int minInsertions(String s) {
    int minInsertions = 0;
    Stack<Character> stack = new Stack<>();
    for (char c : s.toCharArray()) {
        if (c == '(') {
            stack.push(c);
        } else if (c == ')') {
            if (stack.isEmpty()) {
                minInsertions++;
            } else {
                stack.pop();
            }
        } else {
            return -1;
        }
    }
    minInsertions += stack.size();
    return minInsertions;
}
