  int[][] dp = new int[n][n];

  // base case: dp[i][j] = 0, if i = j
  for (int i = 0; i < n; i++) {
    dp[i][i] = 0;
  }

  // fill in the rest of the 2D array using the recurrence relation
  for (int i = 0; i < n - 1; i++) {
    for (int j = i + 1; j < n; j++) {
      dp[i][j] = Integer.MAX_VALUE;
      for (int k = i; k <= j; k++) {
