    // Initialize the string with the smallest letter 'a'
    String smallestString = "a";

    // Loop until the length of the string is equal to n
    while (smallestString.length() < n) {
        // Get the value of the current string
        int value = getValue(smallestString);

        // Check if the value is greater than or equal to k
        if (value >= k) {
            // If the value is greater than or equal to k, we need to decrease the value by 1
            // To do this, we can append the letter 'a' to the string
            smallestString += "a";
        } else {
            // If the value is less than k, we can append the next letter in the alphabet to the string
            smallestString += Character.toString((char) ('a' + (k - value)));
        }
    }

    return smallestString;
}

private int getValue(String str) {
