public class LongestLine {
    public static int longestLine(int[][] mat) {
        // Initialize a set to store the coordinates of all 1s
        Set<String> ones = new HashSet<>();
        for (int i = 0; i < mat.length; i++) {
            for (int j = 0; j < mat[i].length; j++) {
                if (mat[i][j] == 1) {
                    ones.add(i + "," + j);
                }
            }
        }

        // Initialize a map to store the count of each coordinate
        Map<String, Integer> count = new HashMap<>();
        for (String coord : ones) {
            count.put(coord, 0);
        }

        // Traverse the matrix and count the number of 1s in each direction
        for (int i = 0; i < mat.length; i++) {
            for (int j = 0; j < mat[i].length; j++) {
                if (mat[i][j] == 1) {
                    // Count horizontal
                    if (j < mat[i].length - 1 && mat[i][j + 1] == 1) {
                        count.put(i + "," + j, count.get(i + "," + j) + 1);
                    }

                    // Count vertical
                    if (i < mat.length - 1 && mat[i + 1][j] == 1) {
                        count.put(i + "," + j, count.get(i + "," + j) + 1);
                    }

                    // Count diagonal
                    if (i < mat.length - 1 && j < mat[i].length - 1 && mat[i + 1][j + 1] == 1) {
                        count.put(i + "," + j, count.get(i + "," + j) + 1);
                    }

                    // Count anti-diagonal
                    if (i > 0 && j < mat[i].length - 1 && mat[i - 1][j + 1] == 1) {
                        count.put(i + "," + j, count.get(i + "," + j) + 1);
                    }
                }
            }
        }

        // Find the maximum count
        int max = 0;
        for (String coord : count.keySet()) {
            max = Math.max(max, count.get(coord));
        }

        return max;
    }
}
